-- Owner 2026-11-04: "เมืองทองก่อน ราคาเหมือน sms" — import Muangthong Aluminium Vol.3 (แคตตาล็อคเมืองทอง.pdf) as an extruder.
-- Source docs/catalogs/muangthong/muangthong-vol3.json (kg/m + wall read from the catalogue; role names mapped). Prices = SMS
-- shop rates (170 THB/kg, wood grain 350). Pictures uploaded first to estimation-images/<tenant>/profiles/<id>.png with t = wall.
-- Families: STANDARD = GROUP 01 box system (like SMS001 / MN GROUP 01). Generated by 2026-11-04-import-muangthong.gen.py; refuses to run twice.
BEGIN;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM alu_providers WHERE tenant_id = '1b9affc4-2136-4ed1-b168-a36e6624e743' AND (id = 'b4d5db3e-3c47-50bd-ac96-e423a47b128b' OR short_name = 'MT')) THEN RAISE EXCEPTION 'Muangthong already imported'; END IF; END $$;
DO $$ DECLARE a int; b int; c int; d int; e int; f int; BEGIN
  SELECT count(*) INTO a FROM alu_series WHERE provider_id = 'b4d5db3e-3c47-50bd-ac96-e423a47b128b';
  SELECT count(*) INTO b FROM alu_profiles WHERE provider_id = 'b4d5db3e-3c47-50bd-ac96-e423a47b128b';
  SELECT count(*) INTO c FROM alu_series_profiles sp JOIN alu_series s ON s.id = sp.series_id WHERE s.provider_id = 'b4d5db3e-3c47-50bd-ac96-e423a47b128b';
  SELECT count(*) INTO d FROM alu_series_types st JOIN alu_series s ON s.id = st.series_id WHERE s.provider_id = 'b4d5db3e-3c47-50bd-ac96-e423a47b128b';
  SELECT count(*) INTO e FROM alu_kg_prices WHERE provider_id = 'b4d5db3e-3c47-50bd-ac96-e423a47b128b';
  SELECT count(*) INTO f FROM alu_profiles WHERE provider_id = 'b4d5db3e-3c47-50bd-ac96-e423a47b128b' AND image_path IS NOT NULL;
  IF a <> 33 OR b <> 728 OR c <> 733 OR d <> 56 OR e <> 4 OR f <> 728 THEN
    RAISE EXCEPTION 'count mismatch: series % profiles % links % types % prices % images %', a, b, c, d, e, f; END IF;
END $$;
SELECT f.name family, count(DISTINCT s.id) series, count(sp.id) profiles FROM alu_series s JOIN alu_series_families f ON f.id = s.series_family_id LEFT JOIN alu_series_profiles sp ON sp.series_id = s.id WHERE s.provider_id = 'b4d5db3e-3c47-50bd-ac96-e423a47b128b' GROUP BY f.name, f.sort_order ORDER BY f.sort_order;
COMMIT;
